// Coupled two-tank supervisory view (READ-ONLY; no PLC writes).
// Tank1 (Cell-1) = upstream; Tank2 (Cell-2) = downstream buffer.
var t = msg.topic || '';
var v = Number(msg.payload);
if (t.indexOf('cell1/plc1/level') >= 0) flow.set('l1', v);
if (t.indexOf('cell2/plc2/level') >= 0) flow.set('l2', v);
if (t.indexOf('cell1/plc1/pump')  >= 0) flow.set('p1', v);
if (t.indexOf('cell2/plc2/pump')  >= 0) flow.set('p2', v);
var l1 = flow.get('l1'), l2 = flow.get('l2'), p1 = flow.get('p1'), p2 = flow.get('p2');
if (l1 === undefined || l2 === undefined) return null;
var total = Number((l1 + l2).toFixed(1));
var status = 'nominal';
if (l1 < 30 && l2 < 20)        status = 'SUPPLY LOW (both tanks)';
else if (p1 == 1 && l1 > 50)   status = 'Tank1 -> Tank2 transfer active';
else if (l2 > 50)              status = 'Tank2 buffer high';
var pub = [
  { topic: 'cars/system/total',  payload: total },
  { topic: 'cars/system/status', payload: status }
];
return [ pub, { payload: total }, { payload: status } ];
